def transform(grid):
    """Copy the non-background prototype pattern centered on each singleton marker."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x, grid[y][x]))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] != bg:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            comps.append(comp)
    proto = max(comps, key=len)
    r0, r1 = min(p[0] for p in proto), max(p[0] for p in proto)
    c0, c1 = min(p[1] for p in proto), max(p[1] for p in proto)
    ar, ac = (r0+r1)//2, (c0+c1)//2
    proto_cells = {(r,c) for r,c,_ in proto}
    markers = [(r,c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r,c) not in proto_cells]
    out = [row[:] for row in grid]
    for mr, mc in markers:
        for r,c,color in proto:
            rr, cc = mr+r-ar, mc+c-ac
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out

